  1→"use client";
  2→
  3→import {useState} from "react";
  4→import {cn} from "@/lib/utils";
  5→import {DictionaryList} from "@/components/dictionary/dictionary-list";
  6→import {DictionaryOverview} from "@/components/dictionary/dictionary-overview";
  7→import {Button} from "@/components/ui/button";
  8→import {Badge} from "@/components/ui/badge";
  9→import {
 10→    ArrowLeftRight,
 11→    BookOpen,
 12→    FileText,
 13→    Hash,
 14→    Languages,
 15→    LayoutDashboard,
 16→    Puzzle,
 17→    Scale,
 18→    Space,
 19→} from "lucide-react";
 20→import type {DictionaryType, MenuSection} from "@/types";
 21→import {DICTIONARY_TYPE_LABELS} from "@/types";
 22→
 23→interface MenuItem {
 24→    id: MenuSection;
 25→    label: string;
 26→    icon: React.ElementType;
 27→}
 28→
 29→const menuItems: MenuItem[] = [
 30→    {id: 'OVERVIEW', label: '개요', icon: LayoutDashboard},
 31→    {id: 'STOP', label: '불용어', icon: FileText},
 32→    {id: 'USER', label: '사용자 단어', icon: BookOpen},
 33→    {id: 'ENGLISH', label: '영문 단어', icon: Languages},
 34→    {id: 'UNIT', label: '단위', icon: Hash},
 35→    {id: 'SYNONYM', label: '동의어', icon: ArrowLeftRight},
 36→    {id: 'UNIT_SYNONYM', label: '단위 동의어', icon: Scale},
 37→    {id: 'SPACE', label: '공백 분리', icon: Space},
 38→    {id: 'COMPOUND', label: '복합어', icon: Puzzle},
 39→];
 40→
 41→export default function DictionaryPage() {
 42→    const [activeMenu, setActiveMenu] = useState<MenuSection>('OVERVIEW');
 43→
 44→    const getActiveLabel = () => {
 45→        const item = menuItems.find(i => i.id === activeMenu);
 46→        return item?.label || '';
 47→    };
 48→
 49→    const isOverview = activeMenu === 'OVERVIEW';
 50→
 51→    return (
 52→        <div className="flex h-screen gap-6 p-6">
 53→            {/* Sidebar Navigation */}
 54→            <aside className="w-56 flex-shrink-0 space-y-1">
 55→                <div className="flex items-center gap-2 px-3 py-2 mb-4">
 56→                    <BookOpen className="h-5 w-5 text-primary"/>
 57→                    <h2 className="font-semibold">사전 관리</h2>
 58→                </div>
 59→
 60→                {/* Menu Items */}
 61→                <div className="space-y-1">
 62→                    {menuItems.map((item, index) => {
 63→                        const Icon = item.icon;
 64→                        const isActive = activeMenu === item.id;
 65→                        const isOverviewItem = item.id === 'OVERVIEW';
 66→                        return (
 67→                            <div key={item.id}>
 68→                                {/* 개요와 사전 타입 사이에 구분선 추가 */}
 69→                                {index === 1 && (
 70→                                    <div className="my-2 border-t border-border"/>
 71→                                )}
 72→                                <Button
 73→                                    variant={isActive ? "secondary" : "ghost"}
 74→                                    className={cn(
 75→                                        "w-full justify-start gap-2 h-9",
 76→                                        isActive && "bg-secondary font-medium",
 77→                                        isOverviewItem && "text-primary"
 78→                                    )}
 79→                                    onClick={() => setActiveMenu(item.id)}
 80→                                >
 81→                                    <Icon className="h-4 w-4"/>
 82→                                    <span className="flex-1 text-left">{item.label}</span>
 83→                                </Button>
 84→                            </div>
 85→                        );
 86→                    })}
 87→                </div>
 88→            </aside>
 89→
 90→            {/* Main Content */}
 91→            <main className="flex-1 overflow-hidden">
 92→                <div className="h-full flex flex-col">
 93→                    {/* Header */}
 94→                    <div className="flex items-center justify-between pb-4 border-b">
 95→                        <div className="flex items-center gap-3">
 96→                            <h1 className="text-2xl font-bold tracking-tight">
 97→                                {getActiveLabel()}
 98→                            </h1>
 99→                            {!isOverview && (
100→                                <Badge variant="outline" className="text-xs">
101→                                    {DICTIONARY_TYPE_LABELS[activeMenu as DictionaryType]}
